#!/usr/bin/env node
// kar-shingle — Agensi skill script, generated by build.mjs in the sjgant80-hub/kar-shingle repository.
// The KERNEL block below is byte-identical to the logic of the live page (index.html) and to
// kernel.mjs, which the tests and the witness mutation gate run against. No network, no dependencies,
// writes no files: it reads the input you name and prints a JSON report to stdout.
// Powered by the Konomi architecture, created by Thomas Frumkin. MIT licence.
// ---- KERNEL (from index.html) ----
// ---------- core algorithm (kept 1:1 with the spec text above) ----------

const enc = new TextEncoder();

async function sha256Hex(str){
  const buf = await crypto.subtle.digest('SHA-256', enc.encode(str));
  const bytes = new Uint8Array(buf);
  let out = '';
  for (let i=0;i<bytes.length;i++) out += bytes[i].toString(16).padStart(2,'0');
  return out;
}

function normalize(text){
  return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

function shingleSet(normText, k){
  if (!normText) return [];
  const words = normText.split(' ');
  if (words.length < k) return [];
  const seen = new Set();
  for (let i=0;i<=words.length-k;i++){
    seen.add(words.slice(i, i+k).join(' '));
  }
  return [...seen];
}

const MOD32 = 1n << 32n;
let permCache = new Map(); // N -> [{a,b}]

async function getPerms(N){
  if (permCache.has(N)) return permCache.get(N);
  const perms = new Array(N);
  for (let i=0;i<N;i++){
    const ah = await sha256Hex('kar-shingle-perm-a-'+i);
    const bh = await sha256Hex('kar-shingle-perm-b-'+i);
    const a = (BigInt('0x'+ah.slice(0,8)) | 1n);
    const b = BigInt('0x'+bh.slice(0,8));
    perms[i] = {a,b};
  }
  permCache.set(N, perms);
  return perms;
}

// returns { shingleCount, normalized, normalizedSha256, sig (BigInt[] or null), signatureSha256 }
async function analyzeDoc(rawText, k, N){
  const norm = normalize(rawText);
  const normalizedSha256 = await sha256Hex(norm);
  const shs = shingleSet(norm, k);
  if (shs.length === 0){
    return { shingleCount: 0, normalized: norm, normalizedSha256, sig: null, signatureSha256: null };
  }
  const baseHashes = new Array(shs.length);
  for (let i=0;i<shs.length;i++){
    const h = await sha256Hex(shs[i]);
    baseHashes[i] = BigInt('0x'+h.slice(0,8));
  }
  const perms = await getPerms(N);
  const sig = new Array(N);
  for (let i=0;i<N;i++){
    const {a,b} = perms[i];
    let min = null;
    for (let j=0;j<baseHashes.length;j++){
      const v = (a * baseHashes[j] + b) % MOD32;
      if (min === null || v < min) min = v;
    }
    sig[i] = min;
  }
  const sigHex = sig.map(v => v.toString(16).padStart(8,'0')).join('');
  const signatureSha256 = await sha256Hex(sigHex);
  return { shingleCount: shs.length, normalized: norm, normalizedSha256, sig, signatureSha256 };
}

function similarityOf(sigA, sigB){
  if (!sigA || !sigB) return null;
  let match = 0;
  for (let i=0;i<sigA.length;i++) if (sigA[i] === sigB[i]) match++;
  return { matches: match, total: sigA.length, ratio: match / sigA.length };
}

function verdictOf(docA, docB, sim){
  if (docA.shingleCount === 0 || docB.shingleCount === 0) return 'INSUFFICIENT-DATA';
  if (docA.normalizedSha256 === docB.normalizedSha256) return 'IDENTICAL';
  const r = sim.ratio;
  if (r >= 0.75) return 'NEAR-DUPLICATE';
  if (r >= 0.35) return 'OVERLAPPING';
  return 'DISTINCT';
}

function canonJSON(obj){
  if (obj === null || typeof obj !== 'object') return JSON.stringify(obj);
  if (Array.isArray(obj)) return '[' + obj.map(canonJSON).join(',') + ']';
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonJSON(obj[k])).join(',') + '}';
}

async function buildReceipt(k, N, docA, docB, sim, verdict){
  const receipt = {
    algorithm: 'kar-shingle-minhash-v1',
    k, n: N,
    docA: { shingleCount: docA.shingleCount, normalizedSha256: docA.normalizedSha256, signatureSha256: docA.signatureSha256 },
    docB: { shingleCount: docB.shingleCount, normalizedSha256: docB.normalizedSha256, signatureSha256: docB.signatureSha256 },
    similarityMatches: sim ? sim.matches : null,
    similarityTotal: sim ? sim.total : null,
    verdict
  };
  const canon = canonJSON(receipt);
  const hash = await sha256Hex(canon);
  return { receipt, canon, hash };
}

// ---------- self test ----------

const SELF = {
  K: 5, N: 64,
  A: "The quarterly steering committee reviewed the migration plan in detail and agreed that the pilot cohort would move to the new billing platform first, with the remaining regions following in staggered waves once the pilot had run cleanly for two full billing cycles without any reconciliation errors or customer complaints.",
  get B(){ return this.A + " A follow-up review is scheduled for the end of the second cycle."; },
  D: "The quarterly steering committee reviewed the migration plan in detail and agreed that the pilot cohort would shift to the new billing platform first, with the remaining regions following in staggered waves once the pilot had run cleanly for two full billing cycles without any reconciliation errors or customer complaints.",
  C: "Sedimentary rock layers exposed along the canyon wall record millions of years of gradual deposition, with each distinct band reflecting a different era of climate, water flow, and mineral content that geologists can read like pages in a very slow, very patient book."
};

// impl: optional stand-ins for analyzeDoc / similarityOf / verdictOf, so the tests can prove each check
// actually fails on a faulty implementation (a self-test that cannot fail proves nothing). The page passes none.
async function runSelfTest(impl){
  impl = impl || { analyzeDoc: analyzeDoc, similarityOf: similarityOf, verdictOf: verdictOf };
  const rows = [];
  let allPass = true;

  function addRow(label, pass, detail){
    rows.push({label, pass, detail});
    if (!pass) allPass = false;
  }

  try {
    const k = SELF.K, N = SELF.N;
    const a1 = await impl.analyzeDoc(SELF.A, k, N);
    const a2 = await impl.analyzeDoc(SELF.A, k, N);
    const b  = await impl.analyzeDoc(SELF.B, k, N);
    const c  = await impl.analyzeDoc(SELF.C, k, N);
    const d  = await impl.analyzeDoc(SELF.D, k, N);

    // 1. identical resubmission -> IDENTICAL, ratio exactly 1
    const simAA = impl.similarityOf(a1.sig, a2.sig);
    const vAA = impl.verdictOf(a1, a2, simAA);
    addRow('Re-submission verifies as IDENTICAL (ratio=1.0)',
      vAA === 'IDENTICAL' && simAA.ratio === 1,
      'verdict=' + vAA + ' ratio=' + simAA.ratio);

    // 2. disguised duplicate (sentence appended) -> caught as NEAR-DUPLICATE, not IDENTICAL
    const simAB = impl.similarityOf(a1.sig, b.sig);
    const vAB = impl.verdictOf(a1, b, simAB);
    addRow('Padded duplicate is caught as NEAR-DUPLICATE (not IDENTICAL)',
      vAB === 'NEAR-DUPLICATE',
      'verdict=' + vAB + ' ratio=' + simAB.ratio.toFixed(3));

    // 3. disguised duplicate (one word swapped) -> caught as NEAR-DUPLICATE
    const simAD = impl.similarityOf(a1.sig, d.sig);
    const vAD = impl.verdictOf(a1, d, simAD);
    addRow('Word-swap duplicate is caught as NEAR-DUPLICATE',
      vAD === 'NEAR-DUPLICATE',
      'verdict=' + vAD + ' ratio=' + simAD.ratio.toFixed(3));

    // 4. unrelated document -> DISTINCT, no false positive
    const simAC = impl.similarityOf(a1.sig, c.sig);
    const vAC = impl.verdictOf(a1, c, simAC);
    addRow('Unrelated document is not falsely flagged (DISTINCT)',
      vAC === 'DISTINCT',
      'verdict=' + vAC + ' ratio=' + simAC.ratio.toFixed(3));

    // 5. determinism: recomputing A's signature twice gives byte-identical signatureSha256
    addRow('Recomputing the same document twice is byte-identical',
      a1.signatureSha256 === a2.signatureSha256 && a1.normalizedSha256 === a2.normalizedSha256,
      'sigHash match=' + (a1.signatureSha256 === a2.signatureSha256));

    // 6. edge case: too-short document reports INSUFFICIENT-DATA, does not throw
    const short = await impl.analyzeDoc("too few words", k, N);
    addRow('Under-length document reports INSUFFICIENT-DATA safely',
      short.shingleCount === 0,
      'shingleCount=' + short.shingleCount);

  } catch (err){
    addRow('Self-test threw an unexpected error', false, String(err && err.message || err));
  }

  return { pass: allPass, rows };
}

// ---------- parameters and the whole comparison (shared by the page, its receipt check and the skill script) ----------
const MAX_CHARS = 200000;
function clampText(t){
  return t.length > MAX_CHARS ? t.slice(0, MAX_CHARS) : t;
}
function clampParams(k, n){
  return {
    k: Math.max(2, Math.min(10, parseInt(k, 10) || 5)),
    N: Math.max(4, Math.min(256, parseInt(n, 10) || 64))
  };
}
async function compareTexts(textA, textB, k, N){
  const a = await analyzeDoc(clampText(typeof textA === 'string' ? textA : ''), k, N);
  const b = await analyzeDoc(clampText(typeof textB === 'string' ? textB : ''), k, N);
  const sim = similarityOf(a.sig, b.sig);
  const verdict = verdictOf(a, b, sim);
  const bundle = await buildReceipt(k, N, a, b, sim, verdict);
  return { a, b, sim, verdict, bundle };
}
// ---- CLI (from cli.mjs) ----
// cli.mjs — Kar-Shingle on the command line. build.mjs bundles this with the KERNEL block of index.html into
// scripts/kar-shingle.mjs, the single file the Agensi skill runs. It estimates how much word-level text two
// documents share (word shingles + MinHash over SHA-256-derived permutations) and gives a verdict plus a
// receipt anyone can recompute. Exit 0 = a verdict was computed (read "verdict") · 1 = a self-check failed ·
// 2 = the input could not be used.
import { readFileSync } from 'node:fs';

const USAGE = `usage: node kar-shingle.mjs <a.txt> <b.txt>      compare two text files at K=5, N=64 (either may be - for stdin)
       node kar-shingle.mjs <input.json | ->         input: {"a": "text", "b": "text", "k": 5, "n": 64}  (k, n optional)
       node kar-shingle.mjs --selftest               run the page's built-in self-checks
output: a JSON report on stdout with verdict IDENTICAL, NEAR-DUPLICATE, OVERLAPPING, DISTINCT or INSUFFICIENT-DATA.
exit 0 = a verdict was computed, 2 = bad input`;

class InputError extends Error {}
const fail = (msg) => { throw new InputError(msg); };

function readText(path) {
  try { return readFileSync(path === '-' ? 0 : path, 'utf8'); }
  catch (e) { return fail(`cannot read ${path === '-' ? 'stdin' : path}: ${e.code || e.message}`); }
}

async function shingle(textA, textB, kIn, nIn) {
  const { k, N } = clampParams(kIn, nIn);
  const { a, b, sim, verdict, bundle } = await compareTexts(textA, textB, k, N);
  const side = (d) => ({ shingleCount: d.shingleCount, normalizedSha256: d.normalizedSha256, signatureSha256: d.signatureSha256 });
  return {
    tool: 'kar-shingle',
    algorithm: bundle.receipt.algorithm,
    verdict,
    similarity: sim ? { matches: sim.matches, total: sim.total, ratio: sim.ratio } : null,
    k,
    n: N,
    a: side(a),
    b: side(b),
    receipt: { sha256: bundle.hash, canonical: bundle.canon },
  };
}

async function main(args) {
  if (args.length === 1 && args[0] === '--selftest') {
    const r = await runSelfTest();
    const selftest = r.rows.map((x) => ({ name: x.label, ok: x.pass, detail: x.detail }));
    const passed = selftest.filter((t) => t.ok).length;
    process.stdout.write(JSON.stringify({ tool: 'kar-shingle', selftest, passed, total: selftest.length }, null, 2) + '\n');
    return r.pass ? 0 : 1;
  }
  let report;
  if (args.length === 2) {
    if (args[0] === '-' && args[1] === '-') fail('only one of the two documents can come from stdin');
    report = await shingle(readText(args[0]), readText(args[1]));
  } else if (args.length === 1 && args[0] !== '-h' && args[0] !== '--help') {
    let input;
    try { input = JSON.parse(readText(args[0])); } catch (e) { if (e instanceof InputError) throw e; fail(`the input is not valid JSON (${e.message})`); }
    if (!input || typeof input !== 'object' || typeof input.a !== 'string' || typeof input.b !== 'string') {
      fail('a single input must be an object with "a" and "b" (the two texts), and optionally "k" and "n"');
    }
    report = await shingle(input.a, input.b, input.k, input.n);
  } else {
    process.stderr.write(USAGE + '\n');
    return 2;
  }
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  return 0;
}

try {
  process.exitCode = await main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`kar-shingle: ${e instanceof InputError ? e.message : 'internal error: ' + (e && e.message)}\n`);
  process.exitCode = e instanceof InputError ? 2 : 3;
}
